Data Prep

ice_cream &lt;- ice_cream |&gt; 
 # filter(flavor_descr %in% c("CHERRY GRCA", "CHC FUDGE BROWNIE", "CHUNKY MONKEY", "PHISH FOOD", "HEATH COFFEE CRUNCH", "CHC CHIP C-DH")) |&gt; 
  mutate(flavor_descr = factor(flavor_descr),
         flavor_descr = fct_relevel(flavor_descr, "CHERRY GRCA", "CHC FUDGE BROWNIE", "CHUNKY MONKEY", "PHISH FOOD", "HEATH COFFEE CRUNCH", "CHC CHIP C-DH"))

Splitting into Treaining and Test Data

set.seed(9)

ice_cream&lt;- ice_cream |&gt; 
  mutate(rnd = runif(n()))

dtrain&lt;- ice_cream |&gt; 
  filter(rnd &gt; 0.3)

dtest&lt;- ice_cream |&gt; 
  filter(rnd &lt;= 0.3)
